package io.github.devicebridge.android;
import android.app.*;import android.content.*;import android.hardware.usb.*;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.database.Cursor;import android.view.*;import android.widget.*;import io.github.devicebridge.core.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public final class FastbootActivity extends Activity {
 private FastbootClient client;private TextView output,imageLabel;private EditText partition,command;private Uri image;private volatile Future<?> running,imagePreparing;private File preparedImage;private String preparedImageName="",preparedImageSha="";private int imageGeneration;private volatile boolean destroyed;private String imagePickerId;
 private final BroadcastReceiver usb=new BroadcastReceiver(){public void onReceive(Context c,Intent i){UsbDevice d=i.getParcelableExtra(UsbManager.EXTRA_DEVICE);if(d==null)return;if("io.github.devicebridge.FASTBOOT_PERMISSION".equals(i.getAction())){if(i.getBooleanExtra(UsbManager.EXTRA_PERMISSION_GRANTED,false))connect(d);else append("USB授权被拒绝");}else if(UsbManager.ACTION_USB_DEVICE_DETACHED.equals(i.getAction())&&client!=null&&client.target().equals("USB "+d.getDeviceName())){close();append("USB设备已拔出，操作中止");}}};
 public void onCreate(Bundle b){super.onCreate(b);IntentFilter f=new IntentFilter("io.github.devicebridge.FASTBOOT_PERMISSION");f.addAction(UsbManager.ACTION_USB_DEVICE_DETACHED);if(Build.VERSION.SDK_INT>=33)registerReceiver(usb,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(usb,f);
  LinearLayout root=Ui.col(this);Ui.inset(this,root);LinearLayout top=Ui.row(this);top.addView(Ui.button(this,"‹",this::onBackPressed));Ui.expanded(top,Ui.text(this,"Fastboot",20));top.addView(Ui.button(this,"⋮",this::menu));root.addView(top);root.addView(Ui.button(this,"选择USB设备（免ROOT）",this::choose));root.addView(Ui.button(this,"读取设备信息",()->run(client,"设备信息",FastbootClient::deviceInfo)));imageLabel=Ui.text(this,"未选择镜像",13);root.addView(imageLabel);root.addView(Ui.button(this,"选择镜像",()->{if(running!=null&&!running.isDone()){Ui.message(this,"操作进行中","完成当前操作后才能更换镜像。");return;}imagePickerId=UUID.randomUUID().toString();startActivityForResult(LocalFilesActivity.intent(this,LocalFilesActivity.MODE_IMAGE,imagePickerId),1);}));LinearLayout pr=Ui.row(this);Spinner choices=new Spinner(this);choices.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"recovery","boot","自定义分区"}));pr.addView(choices);partition=Ui.edit(this,"分区名");partition.setText("recovery");Ui.expanded(pr,partition);choices.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int n,long id){partition.setText(n==0?"recovery":n==1?"boot":"");}});root.addView(pr);root.addView(Ui.button(this,"刷入镜像",this::flash));ScrollView scroll=new ScrollView(this);output=Ui.text(this,"未连接Fastboot设备\n",12);output.setTypeface(android.graphics.Typeface.MONOSPACE);output.setTextIsSelectable(true);scroll.addView(output);Ui.fill(root,scroll);LinearLayout row=Ui.row(this);command=Ui.edit(this,"Fastboot命令，如 getvar:product");Ui.expanded(row,command);row.addView(Ui.button(this,"运行",this::raw));root.addView(row);setContentView(root);
  SharedPreferences p=getSharedPreferences("settings",MODE_PRIVATE);if(p.getBoolean("show_fastboot_warning",true)){CheckBox skip=new CheckBox(this);skip.setText("不再显示此说明");new AlertDialog.Builder(this).setTitle("Fastboot操作风险").setMessage("刷入错误镜像可能使设备无法启动，擦除分区可能永久丢失数据。只用于你拥有且可以恢复的测试设备。每次刷写仍会单独确认设备、镜像和分区。").setView(skip).setPositiveButton("我已了解",(d,w)->p.edit().putBoolean("show_fastboot_warning",!skip.isChecked()).apply()).show();}}
 private void menu(){new AlertDialog.Builder(this).setItems(new String[]{"清空输出","重启终端","免ROOT运行说明","重启设备","从镜像临时启动"},(d,w)->{if(w==0)output.setText("");else if(w==1){close();append("会话已重置，请重新选择设备");}else if(w==2)Ui.message(this,"免ROOT运行","通过Android USB Host接口直接使用Fastboot，不需要本机ROOT。仍需Android USB授权和目标设备自身的解锁/刷写权限。");else if(w==3)confirm("重启设备","设备会离开Fastboot模式。",target->run(target,"重启",active->active.reboot()));else boot();}).show();}
 private void choose(){if(running!=null&&!running.isDone()){Ui.message(this,"操作进行中","完成或明确取消当前操作后才能选择其他设备。");return;}UsbManager m=(UsbManager)getSystemService(USB_SERVICE);List<UsbDevice> devices=new ArrayList<>();for(UsbDevice d:m.getDeviceList().values())if(UsbTransport.find(d,3)!=null)devices.add(d);if(devices.isEmpty()){Ui.message(this,"Fastboot设备","未发现USB Fastboot接口。普通ADB设备不能用于此页面。");return;}String[] names=new String[devices.size()];for(int i=0;i<names.length;i++)names[i]=devices.get(i).getDeviceName();new AlertDialog.Builder(this).setItems(names,(dialog,n)->{UsbDevice d=devices.get(n);if(m.hasPermission(d))connect(d);else m.requestPermission(d,PendingIntent.getBroadcast(this,1,new Intent("io.github.devicebridge.FASTBOOT_PERMISSION").setPackage(getPackageName()),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}).show();}
 private void connect(UsbDevice d){if(running!=null&&!running.isDone()){append("忽略新设备授权回调，当前设备操作仍在进行");return;}close();try{client=new FastbootClient(new UsbPackets((UsbManager)getSystemService(USB_SERVICE),d),(kind,msg)->append(kind+" "+msg));append("已连接："+client.target());}catch(Exception e){append("连接失败："+e.getMessage());}}
 private void confirm(String title,String detail,java.util.function.Consumer<FastbootClient> action){final FastbootClient bound=client;if(bound==null||bound.isClosed()){Ui.message(this,"未连接","请先选择Fastboot设备");return;}Ui.confirm(this,title,"目标："+bound.target()+"\n"+detail,()->{if(client!=bound||bound.isClosed()){Ui.message(this,"设备会话已改变","原确认已失效，请重新选择设备和操作。");return;}action.accept(bound);});}
 private void flash(){if(preparedImage==null){Ui.message(this,"未选择镜像","请先选择可读镜像文件");return;}final String part=partition.getText().toString().trim();if(!part.matches("[A-Za-z0-9_.-]{1,64}")){Ui.message(this,"分区无效","请输入有效分区名");return;}final File selected=preparedImage;final String selectedSha=preparedImageSha;confirm("刷入镜像","镜像："+preparedImageName+"\n大小："+selected.length()+" B\nSHA256："+selectedSha+"\n分区："+part+"\n此操作将覆盖分区，可能丢失数据或导致设备无法启动。请确认镜像适用于这台设备。",target->run(target,"刷写 "+part,active->{verifyImage(selected,selectedSha);try(InputStream in=new FileInputStream(selected)){active.download(in,selected.length(),(done,total)->{appendProgress(done,total);return !Thread.currentThread().isInterrupted();});return active.flash(part);}}));}
 private void boot(){if(preparedImage==null){Ui.message(this,"未选择镜像","请先选择boot镜像");return;}File chosen=preparedImage;String chosenSha=preparedImageSha;confirm("从镜像临时启动","镜像："+preparedImageName+"\n大小："+chosen.length()+" B\nSHA256："+chosenSha+"\n不主动刷写分区，但镜像启动后能修改设备数据。",target->run(target,"临时启动",active->{verifyImage(chosen,chosenSha);try(InputStream in=new FileInputStream(chosen)){active.download(in,chosen.length(),(d,t)->!Thread.currentThread().isInterrupted());return active.boot();}}));}
 private void raw(){String c=command.getText().toString().trim();if(c.isEmpty())return;confirm("发送Fastboot命令",c+"\n自定义命令可能擦除或修改设备。",target->run(target,c,active->active.executeCommand(c)));}
 private void prepareImage(Uri uri,String name,String expectedToken){int expected=++imageGeneration;if(imagePreparing!=null)imagePreparing.cancel(true);if(preparedImage!=null){LocalSnapshot.dispose(preparedImage);preparedImage=null;}imageLabel.setText("正在缓存并校验镜像…");imagePreparing=BridgeRuntime.IO.submit(()->{File f=null;try{f=cache(uri,expectedToken);String hash=imageHash(f);f.setReadOnly();final File ready=f;BridgeRuntime.UI.post(()->{if(destroyed||imageGeneration!=expected){LocalSnapshot.dispose(ready);return;}preparedImage=ready;preparedImageName=name;preparedImageSha=hash;imageLabel.setText(name+"\n"+ready.length()+" B\nSHA256 "+hash);});}catch(Exception e){if(f!=null)LocalSnapshot.dispose(f);append("镜像准备失败："+e.getMessage());}});}
 private static String imageHash(File file)throws Exception{java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))>=0){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("已取消");digest.update(b,0,n);}}StringBuilder result=new StringBuilder();for(byte v:digest.digest())result.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return result.toString();}
 private static void verifyImage(File file,String sha)throws Exception{if(!file.isFile()||!sha.equals(imageHash(file)))throw new IOException("镜像内容已改变，原确认失效。请重新选择镜像。");}
 private File cache(Uri uri,String expectedToken)throws IOException{LocalSnapshot snapshot=LocalSnapshot.create(this,uri,expectedToken);if(snapshot.bytes==0){LocalSnapshot.dispose(snapshot.file);throw new IOException("镜像为空");}return snapshot.file;}
 private interface Action {String execute(FastbootClient target)throws Exception;}
 private void run(final FastbootClient bound,String title,Action action){if(bound==null||bound.isClosed()||client!=bound){Ui.message(this,"未连接","请先连接Fastboot设备");return;}if(running!=null&&!running.isDone()){Ui.message(this,"操作进行中","请等待当前操作结束");return;}ProgressDialog dialog=new ProgressDialog(this);dialog.setMessage(title+"\n"+bound.target());dialog.setCancelable(false);dialog.setButton(-2,"取消",(d,w)->{if(running!=null)running.cancel(true);try{bound.close();}catch(IOException ignored){}append("已取消；已写入设备的数据不能自动撤销");});dialog.show();running=BridgeRuntime.IO.submit(()->{try{if(client!=bound)throw new IOException("设备会话已改变");append("结果："+action.execute(bound));}catch(Exception e){append("失败："+e.getMessage());}finally{BridgeRuntime.UI.post(()->{if(!destroyed)dialog.dismiss();});}});}
 private long lastProgress;private void appendProgress(long done,long total){long now=System.currentTimeMillis();if(now-lastProgress>1000||done==total){lastProgress=now;append("传输："+done+" / "+total);}}
 private void append(String s){BridgeRuntime.UI.post(()->{if(!destroyed&&output!=null){if(output.length()>512000)output.setText(output.getText().subSequence(256000,output.length()));output.append(s+"\n");}});}
 private void close(){if(running!=null)running.cancel(true);if(client!=null)try{client.close();}catch(IOException ignored){}client=null;}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=1||data==null)return;if(data.hasExtra(LocalFilesActivity.EXTRA_REQUEST_ID)&&!Objects.equals(imagePickerId,data.getStringExtra(LocalFilesActivity.EXTRA_REQUEST_ID))){Ui.message(this,"镜像选择已失效","请重新选择镜像。");return;}if(result==LocalFilesActivity.RESULT_USE_SAF){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),1);return;}if(result!=RESULT_OK||data.getData()==null)return;image=data.getData();String name=image.toString();try{if("file".equals(image.getScheme()))name=new File(image.getPath()).getName();else try(Cursor cursor=getContentResolver().query(image,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0)+" · "+cursor.getLong(1)+" B";}}catch(Exception metadata){append("镜像名称不可读取，将使用URI标识");}ArrayList<String> tokens=data.getStringArrayListExtra("local_picker_source_tokens");prepareImage(image,name,tokens!=null&&!tokens.isEmpty()?tokens.get(0):null);}
 public void onBackPressed(){if(running!=null&&!running.isDone()){Ui.confirm(this,"中断Fastboot操作","正在传输或写入设备。离开会中断操作，已写入的数据无法自动恢复，设备可能无法启动。",()->{close();finish();});}else super.onBackPressed();}
 protected void onDestroy(){destroyed=true;imageGeneration++;if(imagePreparing!=null)imagePreparing.cancel(true);close();if(preparedImage!=null)LocalSnapshot.dispose(preparedImage);try{unregisterReceiver(usb);}catch(Exception ignored){}super.onDestroy();}
 static final class UsbPackets implements FastbootClient.PacketTransport {final UsbDeviceConnection connection;final UsbInterface iface;final UsbEndpoint in,out;final String name;volatile boolean closed;
  UsbPackets(UsbManager m,UsbDevice d)throws IOException{if(!m.hasPermission(d))throw new IOException("USB未授权");iface=UsbTransport.find(d,3);if(iface==null)throw new IOException("不是Fastboot接口");UsbEndpoint ri=null,wo=null;for(int i=0;i<iface.getEndpointCount();i++){UsbEndpoint e=iface.getEndpoint(i);if(e.getType()==2){if(e.getDirection()==128)ri=e;else wo=e;}}if(ri==null||wo==null)throw new IOException("缺少bulk端点");in=ri;out=wo;name=d.getDeviceName();connection=m.openDevice(d);if(connection==null||!connection.claimInterface(iface,true)){if(connection!=null)connection.close();throw new IOException("无法使用USB接口");}}
  public String description(){return "USB "+name;}public byte[] readPacket(int max)throws IOException{byte[] b=new byte[max];if(closed)throw new IOException("会话已关闭");int n=connection.bulkTransfer(in,b,b.length,30000);if(n<=0)throw new IOException("Fastboot USB读取失败或超时");return Arrays.copyOf(b,n);}public void writePacket(byte[] b,int off,int len)throws IOException{while(len>0){if(closed)throw new IOException("会话已关闭");int n=connection.bulkTransfer(out,b,off,Math.min(len,16384),30000);if(n<=0)throw new IOException("Fastboot USB写入失败或超时");off+=n;len-=n;}}public void close(){if(closed)return;closed=true;connection.releaseInterface(iface);connection.close();}}
}
